using Microsoft.AspNetCore.Mvc;
using System;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Collections.Generic;

namespace InternalApi.Controllers
{
    public class WorkflowPayload
    {
        [JsonPropertyName("action")]
        public string Action { get; set; }

        [JsonPropertyName("data")]
        public JsonElement Data { get; set; }
    }

    public class AdminCommand
    {
        public string CommandType { get; set; }
        public string Target { get; set; }
        public bool Elevated { get; set; }
    }

    public class UserRequest
    {
        public string RequestId { get; set; }
        public string Description { get; set; }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class WorkflowController : ControllerBase
    {
        private static readonly Dictionary<string, Type> ActionTypeMap = new()
        {
            { "user_request", typeof(UserRequest) },
            { "admin_command", typeof(AdminCommand) },
            { "status_check", typeof(UserRequest) }
        };

        [HttpPost("execute")]
        public IActionResult Execute([FromBody] WorkflowPayload payload)
        {
            if (string.IsNullOrEmpty(payload?.Action))
                return BadRequest("Action required");

            // Resolve type from action field - no auth check on action type
            if (!ActionTypeMap.TryGetValue(payload.Action, out var targetType))
                return BadRequest("Unknown action");

            object deserialized;
            try
            {
                deserialized = JsonSerializer.Deserialize(payload.Data.GetRawText(), targetType);
            }
            catch (Exception ex)
            {
                return BadRequest($"Deserialization failed: {ex.Message}");
            }

            // Type confusion: attacker sends action=admin_command but
            // the code trusts the deserialized type without verifying caller identity
            if (deserialized is AdminCommand cmd)
            {
                return ExecuteAdminCommand(cmd);
            }
            else if (deserialized is UserRequest req)
            {
                return ProcessUserRequest(req);
            }

            return StatusCode(500, "Unhandled type");
        }

        private IActionResult ExecuteAdminCommand(AdminCommand cmd)
        {
            // DANGEROUS: executes privileged operations
            // In production this deletes resources, modifies configs, etc.
            if (cmd.Elevated)
            {
                // Simulate destructive admin action
                System.IO.File.WriteAllText(
                    $"/var/run/commands/{cmd.Target}.exec",
                    $"ELEVATED:{cmd.CommandType}");
                return Ok(new { status = "executed", elevated = true, target = cmd.Target });
            }
            return Ok(new { status = "executed", elevated = false });
        }

        private IActionResult ProcessUserRequest(UserRequest req)
        {
            return Ok(new { status = "queued", requestId = req.RequestId });
        }
    }
}
